
import axiosInstance from "./axiosInstance";

export const getIncomingData = (page = 0, size = 10, filters = {}) =>
  axiosInstance.get("/WebApplication/Controllers/getAll", {
    params: {
      page,
      size,
      partName: filters.partName || "",
      supplierName: filters.supplierName || "",
      partType: filters.partType || "",
      lotNumber: filters.lotNumber || "",
      category: filters.category || "" 
    }
  });


  export const getQuarantineData = (page = 0, size = 10, filters = {}) =>
  axiosInstance.get("/WebApplication/Controllers/getAllQuarantine", {
    params: {
      page,
      size,
      partName: filters.partName || "",
      supplierName: filters.supplierName || "",
      partType: filters.partType || "",
      lotNumber: filters.lotNumber || "",
      category: filters.category || "" 
    }
  });

