export const saveQaAction = (formData) =>
  axiosInstance.post("/WebApplication/Controllers/qaAction", formData, {
    headers: {
      "Content-Type": "multipart/form-data"
    }
  });

export const allSupplierName = (data) =>
  axiosInstance.get("/WebApplication/Controllers/getAllSupplier", data);

export const getHistoryLogs = (incomingId) =>
  axiosInstance.get("/WebApplication/Controllers/getHistory", {
    params: { incomingId }
  });