import React, { useState } from "react";
import { NavLink, Outlet, useLocation, useNavigate } from "react-router-dom";
import Pager from "../../component/Pager"; // adjust path as needed

const ReprintModule = () => {
    const location = useLocation();
    const navigate = useNavigate();

    // ── Shared Pagination State (passed to child routes via Outlet context) ──
    const [page, setPage] = useState(0);
    const [pageSize, setPageSize] = useState(10);
    const [totalRows, setTotalRows] = useState(0);
    const totalPages = Math.ceil(totalRows / pageSize) || 1;

    const isIncoming  = location.pathname.includes("incoming");
    const isQuarantine = location.pathname.includes("quarantine");
    const isQualityPrint = location.pathname.includes("quality-print");

    const title = isIncoming
        ? "Incoming Reprint"
        : isQuarantine
            ? "Quarantine Reprint"
            : isQualityPrint
                ? "Quality Reprint"
                : "Reprint Module";

// ── Filters ─────────────────────────────────────────────
    const [filters, setFilters] = useState({
        partName: "",
        category: "",
        supplierName: "",
        partType: "",
        lotNumber: ""
    });

    const handleFilterChange = (field, value) => {
        setPage(0);
        setFilters(prev => ({ ...prev, [field]: value }));
    };

    return (
        <div style={{ display: "flex", flexDirection: "column", height: "100%", overflow: "hidden",margin : "10px 10px" }}>

            {/* ── TOP HEADER BAR ── */}
            <div style={{
                background: "#0f6b5b",
                color: "white",
                padding: "0 20px",
                height: "52px",
                display: "flex",
                alignItems: "center",
                justifyContent: "flex-end"
            }}>
                <h5 style={{ margin: 0, fontWeight: 600 }}>
                    🗂 Quality Window — Reprint
                </h5>
            </div>

            {/* ── TABS ── */}
            <div style={{
                background: "#ffffff",
                borderBottom: "2px solid #dee2e6",
                display: "flex",
                gap: 0,
                flexShrink: 0
            }}>
                {[
                    { to: "/WebApplication/quality/reprint/incoming",      label: "Incoming Reprint" },
                    { to: "/WebApplication/quality/reprint/quality-print", label: "Quality Reprint" },
                    { to: "/WebApplication/quality/reprint/quarantine",    label: "Quarantine Reprint" },
                ].map(({ to, label }) => (
                    <NavLink
                        key={to}
                        to={to}
                        style={({ isActive }) => ({
                            padding: "10px 20px",
                            fontSize: "13px",
                            fontWeight: 500,
                            textDecoration: "none",
                            borderBottom: isActive ? "3px solid #0f6b5b" : "3px solid transparent",
                            color: isActive ? "#0f6b5b" : "#6c757d",
                            background: "white",
                            transition: "all 0.15s"
                        })}
                    >
                        {label}
                    </NavLink>
                ))}
            </div>

            {/* ── CHILD ROUTE CONTENT (fills remaining space) ── */}
            <div style={{ flex: 1, overflow: "hidden", display: "flex", flexDirection: "column" }}>
                <Outlet context={{ page, setPage, totalRows, setTotalRows, pageSize, setPageSize }} />
            </div>

            {/* ── PAGER (sticky at bottom) ── */}
            <Pager
                currentPage={page}
                totalPages={totalPages}
                onPageChange={(p) => setPage(p)}
                pageSize={pageSize}
                onPageSizeChange={(s) => { setPageSize(s); setPage(0); }}
            />
        </div>
    );
};

export default ReprintModule;




