import React, { useEffect, useState } from "react";
import { Table, Modal, Button, Form } from "react-bootstrap";
import * as XLSX from "xlsx";
import {
    getIncomingData,
    allSupplierName,
    saveQaAction,
    getHistoryLogs
} from "../../api/qualityApi";
import Pager from "../../component/Pager"; // adjust path as needed
import "../../css/IncomingModule.css";

const IncomingModule = () => {
    const [data, setData] = useState([]);
    const [selectedRow, setSelectedRow] = useState(null);
    const [showModal, setShowModal] = useState(false);
    const [partType, setPartType] = useState("");
    const [passType, setPassType] = useState("BATCH");
    const [docFile, setDocFile] = useState(null);
    const [showDocModal, setShowDocModal] = useState(false);
    const [docUrl, setDocUrl] = useState("");
    const [docType, setDocType] = useState("");
    const [showHistoryModal, setShowHistoryModal] = useState(false);
    const [historyData, setHistoryData] = useState([]);
    const [remark, setRemark] = useState("");
    const [excelData, setExcelData] = useState([]);
    const [excelHeaders, setExcelHeaders] = useState([]);

    // ── Pagination ──────────────────────────────────────────
    const [page, setPage] = useState(0);
    const [pageSize, setPageSize] = useState(10);
    const [totalRows, setTotalRows] = useState(0);
    const totalPages = Math.ceil(totalRows / pageSize) || 1;

    // ── Filters ─────────────────────────────────────────────
    const [filters, setFilters] = useState({
        partName: "",
        category: "",
        supplierName: "",
        partType: "",
        lotNumber: ""
    });

    // ── Data fetching ────────────────────────────────────────
    const fetchIncoming = async () => {
        try {
            const res = await getIncomingData(page, pageSize, filters);
            setData(res.data?.data || []);
            setTotalRows(res.data?.total || 0);
        } catch (err) {
            console.error(err);
            setData([]);
        }
    };

    useEffect(() => {
        const delay = setTimeout(() => { fetchIncoming(); }, 400);
        return () => clearTimeout(delay);
    }, [page, pageSize, filters]);



    useEffect(() => {

    // Initial fetch
    fetchIncoming();

    // 🔥 Auto refresh every 4 seconds
    const interval = setInterval(() => {
        fetchIncoming();
    }, 4000);

    return () => clearInterval(interval);

}, [page, pageSize, filters]);

    // ── Excel preview ────────────────────────────────────────
    const loadExcelPreview = async (url) => {
        try {
            const res = await fetch(url);
            const blob = await res.blob();
            const arrayBuffer = await blob.arrayBuffer();
            const workbook = XLSX.read(arrayBuffer, { type: "array" });
            const worksheet = workbook.Sheets[workbook.SheetNames[0]];
            const jsonData = XLSX.utils.sheet_to_json(worksheet, { defval: "" });
            setExcelHeaders(jsonData.length > 0 ? Object.keys(jsonData[0]) : []);
            setExcelData(jsonData);
        } catch (err) {
            console.error("Excel preview error:", err);
        }
    };

    // ── Handlers ─────────────────────────────────────────────
    const resetForm = () => {
        setPartType("");
        setPassType("BATCH");
        setDocFile(null);
        setRemark("");
    };

    const handleRowDoubleClick = (row) => {
        const qa = (row.qa || "").trim().toUpperCase();
        if (["EXPIRED", "RERELEASED", "SCRAPPED", "SENT BACK"].includes(qa)) return;
        if (row.status === "1" || row.status === "2") return;
        resetForm();
        setSelectedRow(row);
        setShowModal(true);
    };

    const handleAction = async (type) => {
        try {
            const formData = new FormData();
            formData.append("incomingId", selectedRow.incomingMaterialId);
            formData.append("qaStatus", type);
            formData.append("partType", partType);
            formData.append("passType", passType);
            formData.append("remark", remark);
            formData.append("moduleType", "INCOMING");
            if (docFile) formData.append("document", docFile);
            await saveQaAction(formData);
            setShowModal(false);
            resetForm();
            fetchIncoming();
        } catch {
            alert("Error saving data");
        }
    };

    const openHistory = async (row) => {
        try {
            const res = await getHistoryLogs(row.incomingMaterialId);
            setHistoryData(res.data || []);
            setShowHistoryModal(true);
        } catch {
            alert("Failed to fetch history");
        }
    };

    const handleFilterChange = (field, value) => {
        setPage(0);
        setFilters(prev => ({ ...prev, [field]: value }));
    };

    // ── Status badge helper ──────────────────────────────────
    const statusClass = (qa) => {
        if (!qa) return "status-badge pending";
        const upper = qa.trim().toUpperCase();
        if (upper === "RELEASED") return "status-badge released";
        if (upper === "REJECTED") return "status-badge rejected";
         if (upper === "EXPIRED") return "status-badge expired";
        return "status-badge pending";
    };

    // ── Render ───────────────────────────────────────────────
    return (
        <div style={{ display: "flex", flexDirection: "column", height: "100%", overflow: "hidden"
            ,margin : "10px 10px"
         }}>

            {/* ── TOP HEADER BAR (matches master layout) ── */}
            <div style={{
                background: "#0f6b5b",
                color: "white",
                padding: "0 20px",
                height: "52px",
                display: "flex",
                alignItems: "center",
                justifyContent: "flex-end"
            }}>
                <h5 style={{ margin: 0, fontWeight: 600 }}>
                    🗂 Quality Window — Incoming
                </h5>
            </div>

            {/* ── FILTER ROW (below header, above table) ── */}
            <div style={{
                background: "#ffffff",
                borderBottom: "1px solid #dee2e6",
                padding: "8px 16px",
                display: "flex",
                gap: "10px",
                flexWrap: "wrap",
                flexShrink: 0
            }}>
                {[
                    { placeholder: "Part Name",  field: "partName" },
                    { placeholder: "Category",   field: "category" },
                    { placeholder: "Supplier",   field: "supplierName" },
                    { placeholder: "Part Type",  field: "partType" },
                    { placeholder: "Lot No",     field: "lotNumber" },
                ].map(({ placeholder, field }) => (
                    <input
                        key={field}
                        placeholder={placeholder}
                        onChange={(e) => handleFilterChange(field, e.target.value)}
                        style={{
                            height: "32px",
                            padding: "0 10px",
                            fontSize: "13px",
                            border: "1px solid #ced4da",
                            borderRadius: "4px",
                            outline: "none",
                            minWidth: "130px",
                            flex: "1 1 130px"
                        }}
                    />
                ))}
            </div>

            {/* ── TABLE (flex-grow, scrollable) ── */}
            <div style={{ flex: 1, overflow: "auto" }}>
                <Table
                    bordered
                    hover
                    size="sm"
                    style={{ marginBottom: 0, fontSize: "13px", whiteSpace: "nowrap" }}
                >
                    <thead style={{ position: "sticky", top: 0, zIndex: 1 }}>
                        <tr style={{ background: "#0f6b5b", color: "white" }}>
                            {["S.No", "Part Name", "Category", "Supplier", "Part Type",
                              "Lot No", "Qty", "MFG Date", "Expire Date", "Status",
                              "Remark", "Document", "History"].map(h => (
                                <th key={h} style={{
                                    background: "#0f6b5b", color: "white",
                                    fontWeight: 500, padding: "8px 10px", border: "none"
                                }}>{h}</th>
                            ))}
                        </tr>
                    </thead>
                    <tbody>
                        {Array.isArray(data) && data.length > 0 ? data.map((row, index) => (
                            <tr
                                key={row.incomingMaterialId}
                                onDoubleClick={() => handleRowDoubleClick(row)}
                                style={{
                                    cursor: "pointer",
                                    background: (row.qa || "").trim().toUpperCase() === "EXPIRED"
                                        ? "#fff3cd" : index % 2 === 0 ? "#ffffff" : "#f8f9fa"
                                }}
                            >
                                <td style={{ padding: "6px 10px" }}>{index + 1 + page * pageSize}</td>
                                <td style={{ padding: "6px 10px", fontWeight: 500 }}>{row.partName}</td>
                                <td style={{ padding: "6px 10px" }}>{row.category || "-"}</td>
                                <td style={{ padding: "6px 10px" }}>{row.supplierName || "-"}</td>
                                <td style={{ padding: "6px 10px" }}>{row.partType || "-"}</td>
                                <td style={{ padding: "6px 10px" }}>{row.lotNumber}</td>
                                <td style={{ padding: "6px 10px" }}>{row.quantity}</td>
                                <td style={{ padding: "6px 10px" }}>{row.mfgDate}</td>
                                <td style={{ padding: "6px 10px" }}>{row.expireDate}</td>
                                <td style={{ padding: "6px 10px" }}>
                                    <span className={statusClass(row.qa)}>
                                        {(row.qa || "").trim().toUpperCase() || "PENDING"}
                                    </span>
                                </td>
                                <td style={{ padding: "6px 10px" }}>{row.remark || "-"}</td>
                                <td style={{ padding: "6px 10px" }}>
                                    {row.qaDocPath ? (
                                        <Button size="sm" variant="info" style={{ fontSize: "11px", padding: "2px 8px" }}
                                            onClick={() => {
                                                const url = `${window.location.origin}/WebApplication/Controllers/viewDoc?path=${row.qaDocPath}`;
                                                setDocUrl(url);
                                                const ext = row.qaDocPath.split(".").pop().toLowerCase();
                                                setDocType(ext);
                                                if (ext === "xls" || ext === "xlsx") loadExcelPreview(url);
                                                setShowDocModal(true);
                                            }}>View</Button>
                                    ) : "-"}
                                </td>
                                <td style={{ padding: "6px 10px" }}>
                                    <Button size="sm" variant="secondary"
                                        style={{ fontSize: "11px", padding: "2px 8px" }}
                                        onClick={() => openHistory(row)}>
                                        History
                                    </Button>
                                </td>
                            </tr>
                        )) : (
                            <tr>
                                <td colSpan={13} style={{ textAlign: "center", padding: "40px", color: "#999" }}>
                                    No Data Available
                                </td>
                            </tr>
                        )}
                    </tbody>
                </Table>
            </div>

            {/* ── PAGER (sticky at bottom, matches master) ── */}
            <Pager
                currentPage={page}
                totalPages={totalPages}
                onPageChange={(p) => setPage(p)}
                pageSize={pageSize}
                onPageSizeChange={(s) => { setPageSize(s); setPage(0); }}
            />

            {/* ── QA ACTION MODAL ── */}
            <Modal show={showModal} onHide={() => setShowModal(false)}>
                <Modal.Header closeButton style={{ background: "#0f6b5b", color: "white" }}>
                    <Modal.Title>QA Action</Modal.Title>
                </Modal.Header>
                <Modal.Body>
                    <Form>
                        <Form.Group className="mt-2">
                            <Form.Label>Pass</Form.Label>
                            <Form.Select value={passType} onChange={(e) => setPassType(e.target.value)}>
                                <option value="BATCH">Batch</option>
                                <option value="LOT">Lot</option>
                            </Form.Select>
                        </Form.Group>
                        <Form.Group className="mt-2">
                            <Form.Label>Remark</Form.Label>
                            <Form.Control as="textarea" rows={2} value={remark}
                                onChange={(e) => setRemark(e.target.value)} placeholder="Enter remark..." />
                        </Form.Group>
                        <Form.Group className="mt-2">
                            <Form.Label>Upload Document</Form.Label>
                            <Form.Control type="file" onChange={(e) => setDocFile(e.target.files[0])} />
                        </Form.Group>
                        <Form.Group className="mt-2">
                            <Form.Label>Part Type</Form.Label>
                            <Form.Control type="text" value={partType}
                                onChange={(e) => setPartType(e.target.value)} />
                        </Form.Group>
                        <Form.Group className="mb-2">
                            <Form.Label>MFG Date</Form.Label>
                            <Form.Control value={selectedRow?.mfgDate || ""} readOnly />
                        </Form.Group>
                        <Form.Group className="mb-2">
                            <Form.Label>Expire Date</Form.Label>
                            <Form.Control value={selectedRow?.expireDate || ""} readOnly />
                        </Form.Group>
                    </Form>
                </Modal.Body>
                <Modal.Footer>
                    <Button variant="success" onClick={() => handleAction("RELEASED")}>Release</Button>
                    <Button variant="danger" onClick={() => handleAction("REJECTED")}>Reject</Button>
                </Modal.Footer>
            </Modal>

            {/* ── DOCUMENT VIEW MODAL ── */}
            <Modal show={showDocModal} onHide={() => setShowDocModal(false)} size="lg">
                <Modal.Header closeButton>
                    <Modal.Title>View Document</Modal.Title>
                </Modal.Header>
                <Modal.Body style={{ height: "500px" }}>
                    {docType === "pdf" && (
                        <iframe src={docUrl} width="100%" height="100%" style={{ border: "none" }} title="PDF Viewer" />
                    )}
                    {["jpg", "jpeg", "png"].includes(docType) && (
                        <img src={docUrl} alt="Document" style={{ width: "100%", height: "100%", objectFit: "contain" }} />
                    )}
                    {["xls", "xlsx"].includes(docType) && (
                        <div style={{ overflow: "auto", height: "100%" }}>
                            <table style={{ width: "100%", borderCollapse: "collapse" }}>
                                <thead>
                                    <tr>{excelHeaders.map((h, i) => (
                                        <th key={i} style={{ background: "#198754", color: "#fff", padding: "8px", border: "1px solid #ddd" }}>{h}</th>
                                    ))}</tr>
                                </thead>
                                <tbody>
                                    {excelData.map((row, i) => (
                                        <tr key={i} style={{ background: i % 2 === 0 ? "#fff" : "#fafafa" }}>
                                            {excelHeaders.map((h, j) => (
                                                <td key={j} style={{ padding: "6px 10px", border: "1px solid #ddd", fontSize: "13px" }}>{row[h]}</td>
                                            ))}
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    )}
                    {!["pdf","jpg","jpeg","png","xls","xlsx"].includes(docType) && (
                        <div><p>Preview not supported.</p><a href={docUrl} target="_blank" rel="noreferrer">Download File</a></div>
                    )}
                </Modal.Body>
                <Modal.Footer>
                    <Button variant="secondary" onClick={() => setShowDocModal(false)}>Close</Button>
                </Modal.Footer>
            </Modal>

            {/* ── HISTORY MODAL ── */}
            <Modal show={showHistoryModal} onHide={() => setShowHistoryModal(false)} size="lg" centered>
                <Modal.Header closeButton style={{ background: "linear-gradient(135deg, #0f5132, #198754)", color: "white" }}>
                    <Modal.Title className="fw-bold">QA History Logs</Modal.Title>
                </Modal.Header>
                <Modal.Body style={{ background: "#f8f9fa" }}>
                    <div style={{ background: "white", borderRadius: "12px", padding: "15px", maxHeight: "400px", overflowY: "auto" }}>
                        <Table bordered hover responsive className="align-middle mb-0">
                            <thead style={{ background: "#198754", color: "white" }}>
                                <tr>
                                    <th>S.No</th><th>QA Status</th><th>Created By</th>
                                    <th>Remark</th><th>Status</th><th>Date Time</th>
                                </tr>
                            </thead>
                            <tbody>
                                {historyData.length > 0 ? historyData.map((log, index) => (
                                    <tr key={log.qualityIncomingId}>
                                        <td className="text-center fw-semibold">{index + 1}</td>
                                        <td>
                                            <span style={{
                                                padding: "4px 10px", borderRadius: "20px", fontSize: "12px", fontWeight: 600,
                                                background: log.qaStatus?.toUpperCase() === "RELEASED" ? "#d1e7dd" : log.qaStatus?.toUpperCase() === "REJECTED" ? "#f8d7da" : "#fff3cd",
                                                color: log.qaStatus?.toUpperCase() === "RELEASED" ? "#0f5132" : log.qaStatus?.toUpperCase() === "REJECTED" ? "#842029" : "#664d03"
                                            }}>{log.qaStatus || "PENDING"}</span>
                                        </td>
                                        <td>{log.createdBy || "-"}</td>
                                        <td>{log.remark || "-"}</td>
                                        <td><span style={{ padding: "4px 10px", borderRadius: "10px", fontSize: "12px", background: "#e9ecef" }}>{log.status || "-"}</span></td>
                                        <td style={{ fontSize: "13px", color: "#555" }}>{log.dateTimeCreation || "-"}</td>
                                    </tr>
                                )) : (
                                    <tr><td colSpan={6} className="text-center text-muted py-3 fw-semibold">No History Found</td></tr>
                                )}
                            </tbody>
                        </Table>
                    </div>
                </Modal.Body>
                <Modal.Footer style={{ background: "#f8f9fa" }}>
                    <Button variant="secondary" onClick={() => setShowHistoryModal(false)}>Close</Button>
                </Modal.Footer>
            </Modal>
        </div>
    );
};

export default IncomingModule;






