import React, { useEffect, useState } from "react";
import { Table, Button } from "react-bootstrap";
import { getIncomingReprint, reprintIncoming } from "../../api/incomingReprintApi";
import { useOutletContext } from "react-router-dom";
import "../../css/IncomingModule.css";

const IncomingReprint = () => {

    const { page, setPage, totalRows, setTotalRows } = useOutletContext();

    const [data, setData] = useState([]);

    const [filters, setFilters] = useState({
        partName: "",
        category: "",
        supplierName: "",
        partType: "",
        lotNumber: ""
    });

    const pageSize = 10;
    const totalPages = Math.ceil(totalRows / pageSize) || 1;

    // Fetch
    const fetchIncoming = async () => {
        try {
            const res = await getIncomingReprint(page, pageSize, filters);
            setData(res.data?.data || []);
            setTotalRows(res.data?.total || 0);
        } catch (err) {
            console.error(err);
            setData([]);
        }
    };

    useEffect(() => {
        const delay = setTimeout(fetchIncoming, 400);
        return () => clearTimeout(delay);
    }, [page, filters]);

    const handlePrint = async (id) => {
        try {
            const res = await reprintIncoming(id);
            alert(res.data.message);
        } catch {
            alert("Print failed");
        }
    };

    const handleFilterChange = (field, value) => {
        setPage(0);
        setFilters(prev => ({ ...prev, [field]: value }));
    };

    // Same status logic as IncomingModule
    const statusClass = (qa) => {
        if (!qa) return "status-badge pending";
        const upper = qa.trim().toUpperCase();
        if (upper === "RELEASED") return "status-badge released";
        if (upper === "REJECTED" || upper === "EXPIRED") return "status-badge rejected";
        return "status-badge pending";
    };

    return (
        <div style={{ display: "flex", flexDirection: "column", height: "100%", overflow: "hidden",margin : "10px 10px" }}>

            {/* HEADER */}
            {/* <div style={{
                background: "#0f6b5b",
                color: "white",
                padding: "0 20px",
                height: "52px",
                display: "flex",
                alignItems: "center",
                justifyContent: "flex-end"
            }}>
                <h5 style={{ margin: 0, fontWeight: 600 }}>
                    🖨 Incoming Reprint
                </h5>
            </div> */}

            {/* FILTER ROW */}
            <div style={{
                background: "#ffffff",
                borderBottom: "1px solid #dee2e6",
                padding: "8px 16px",
                display: "flex",
                gap: "10px",
                flexWrap: "wrap"
            }}>
                {[
                    { placeholder: "Part Name", field: "partName" },
                    { placeholder: "Category", field: "category" },
                    { placeholder: "Supplier", field: "supplierName" },
                    { placeholder: "Part Type", field: "partType" },
                    { placeholder: "Lot No", field: "lotNumber" },
                ].map(({ placeholder, field }) => (
                    <input
                        key={field}
                        placeholder={placeholder}
                        onChange={(e) => handleFilterChange(field, e.target.value)}
                        style={{
                            height: "32px",
                            padding: "0 10px",
                            fontSize: "13px",
                            border: "1px solid #ced4da",
                            borderRadius: "4px",
                            outline: "none",
                            minWidth: "130px",
                            flex: "1 1 130px"
                        }}
                    />
                ))}
            </div>

            {/* TABLE */}
            <div style={{ flex: 1, overflow: "auto" }}>
                <Table
                    bordered
                    hover
                    size="sm"
                    style={{ marginBottom: 0, fontSize: "13px", whiteSpace: "nowrap" }}
                >
                    <thead style={{ position: "sticky", top: 0, zIndex: 1 }}>
                        <tr style={{ background: "#0f6b5b", color: "white" }}>
                            {[
                                "S.No", "Part Name", "Category", "Supplier", "Part Type",
                                "Lot No", "Qty", "MFG Date", "Expire Date", "Status", "Print"
                            ].map(h => (
                                <th key={h} style={{
                                    background: "#0f6b5b",
                                    color: "white",
                                    fontWeight: 500,
                                    padding: "8px 10px",
                                    border: "none"
                                }}>
                                    {h}
                                </th>
                            ))}
                        </tr>
                    </thead>

                    <tbody>
                        {Array.isArray(data) && data.length > 0 ? (
                            data.map((row, index) => (
                                <tr
                                    key={row.incomingMaterialId}
                                    style={{
                                        background: (row.qa || "").toUpperCase() === "EXPIRED"
                                            ? "#fff3cd"
                                            : index % 2 === 0 ? "#ffffff" : "#f8f9fa"
                                    }}
                                >
                                    <td style={{ padding: "6px 10px" }}>{index + 1 + page * pageSize}</td>
                                    <td style={{ padding: "6px 10px", fontWeight: 500 }}>{row.partName}</td>
                                    <td style={{ padding: "6px 10px" }}>{row.category || "-"}</td>
                                    <td style={{ padding: "6px 10px" }}>{row.supplierName || "-"}</td>
                                    <td style={{ padding: "6px 10px" }}>{row.partType || "-"}</td>
                                    <td style={{ padding: "6px 10px" }}>{row.lotNumber}</td>
                                    <td style={{ padding: "6px 10px" }}>{row.quantity}</td>
                                    <td style={{ padding: "6px 10px" }}>{row.mfgDate}</td>
                                    <td style={{ padding: "6px 10px" }}>{row.expireDate}</td>

                                    <td style={{ padding: "6px 10px" }}>
                                        <span className={statusClass(row.qa)}>
                                            {(row.qa || "").toUpperCase() || "PENDING"}
                                        </span>
                                    </td>

                                    <td style={{ padding: "6px 10px" }}>
                                        <Button
                                            size="sm"
                                            variant="primary"
                                            onClick={() => handlePrint(row.incomingMaterialId)}
                                        >
                                            Print
                                        </Button>
                                    </td>
                                </tr>
                            ))
                        ) : (
                            <tr>
                                <td colSpan={11} style={{ textAlign: "center", padding: "40px", color: "#999" }}>
                                    No Data Available
                                </td>
                            </tr>
                        )}
                    </tbody>
                </Table>
            </div>

        </div>
    );
};

export default IncomingReprint;


