import './App.css';
import 'bootstrap/dist/css/bootstrap.min.css';

import {
  BrowserRouter as Router,
  Route,
  Routes,
  Navigate
} from "react-router-dom";

import IncomingModule from './pages/Qualitypages/IncomingModule';
import QuarantineModule from './pages/Qualitypages/QuarantineModule';
import QualityDashboard from './pages/Qualitypages/QualityDashboard';

import IncomingReprint from './pages/Qualitypages/IncomingReprint';
import QualityReprint from './pages/Qualitypages/QualityReprint';
import QuarantineReprint from './pages/Qualitypages/QuarantineReprint';

import ReprintModule from './pages/Qualitypages/ReprintModule';
import Logout from "./pages/Logout";

function App() {
  return (
    <Router>
      <Routes>

        {/* ✅ QUALITY MAIN LAYOUT */}
        <Route path="/WebApplication/quality/*" element={<QualityDashboard />}>

          {/* Default redirect */}
          <Route index element={<Navigate to="incoming" replace />} />

          {/* ✅ NOW THESE WILL WORK */}
          <Route path="incoming" element={<IncomingModule />} />
          <Route path="quarantine" element={<QuarantineModule />} />

          {/* ✅ Reprint nested inside quality */}
          <Route path="reprint/*" element={<ReprintModule />}>
            <Route index element={<Navigate to="incoming" replace />} />
            <Route path="incoming" element={<IncomingReprint />} />
            <Route path="quality-print" element={<QualityReprint />} />
            <Route path="quarantine" element={<QuarantineReprint />} />
          </Route>

        </Route>

        {/* Optional direct access (if needed) */}
        <Route path="/WebApplication/qualityIncoming" element={<IncomingModule />} />
        <Route path="/WebApplication/quarantineWindow" element={<QuarantineModule />} />

        {/* Logout */}
        <Route path="/WebApplication/logout" element={<Logout />} />

      </Routes>
    </Router>
  );
}

export default App;



