import axiosInstance from "./axiosInstance";

export const getQuarantineReprint = (page = 0, size = 10, filters = {}) =>
  axiosInstance.get("/WebApplication/Controllers/getQuarantineReprint", {
    params: {
      page,
      size,
      partName: filters.partName || "",
      supplierName: filters.supplierName || "",
      partType: filters.partType || "",
      lotNumber: filters.lotNumber || "",
      category: filters.category || "" 
    }
  });
  export const reprintgetQuarantine = (id) => {
    return axiosInstance.post("/WebApplication/Controllers/reprintQA", {
        incomingMaterialId: id
    });
};