import React, { useEffect, useState } from "react";
import { Table, Modal, Button, Form } from "react-bootstrap";
import * as XLSX from "xlsx";
import {
    getQuarantineData,
    saveQaAction,
    getHistoryLogs
} from "../../api/qualityApi";
import Pager from "../../component/Pager";
import "../../css/QuarantineModule.css";

const QuarantineModule = () => {

    const [data, setData] = useState([]);
    const [selectedRow, setSelectedRow] = useState(null);

    const [showModal, setShowModal] = useState(false);
    const [showDocModal, setShowDocModal] = useState(false);
    const [showHistoryModal, setShowHistoryModal] = useState(false);

    const [historyData, setHistoryData] = useState([]);

    const [docFile, setDocFile] = useState(null);
    const [docUrl, setDocUrl] = useState("");
    const [docType, setDocType] = useState("");

    const [partType, setPartType] = useState("");
    const [passType, setPassType] = useState("BATCH");
    const [remark, setRemark] = useState("");

    const [excelData, setExcelData] = useState([]);
    const [excelHeaders, setExcelHeaders] = useState([]);

    // Pagination
    const [page, setPage] = useState(0);
    const [pageSize, setPageSize] = useState(10);
    const [totalRows, setTotalRows] = useState(0);
    const totalPages = Math.ceil(totalRows / pageSize) || 1;

    // Filters
    const [filters, setFilters] = useState({
        partName: "",
        category: "",
        supplierName: "",
        partType: "",
        lotNumber: ""
    });

    // Fetch Data
    const fetchData = async () => {
        try {
            const res = await getQuarantineData(page, pageSize, filters);

            const filtered = (res.data?.data || []).filter(row => {
                const qa = (row.qa || "").trim().toUpperCase();
                return ["REJECTED", "EXPIRED", "SCRAPPED", "RERELEASED", "SENT BACK"].includes(qa);
            });

            setData(filtered);
            setTotalRows(res.data?.total || 0);
        } catch (err) {
            console.error(err);
            setData([]);
        }
    };

    useEffect(() => {
        const delay = setTimeout(fetchData, 400);
        return () => clearTimeout(delay);
    }, [page, pageSize, filters]);

        useEffect(() => {
    
        // Initial fetch
        fetchData();
    
        // 🔥 Auto refresh every 4 seconds
        const interval = setInterval(() => {
            fetchData();
        }, 4000);
    
        return () => clearInterval(interval);
    
    }, [page, pageSize, filters]);
    

    // Excel Preview
    const loadExcelPreview = async (url) => {
        try {
            const res = await fetch(url);
            const blob = await res.blob();
            const buffer = await blob.arrayBuffer();

            const workbook = XLSX.read(buffer, { type: "array" });
            const sheet = workbook.Sheets[workbook.SheetNames[0]];
            const json = XLSX.utils.sheet_to_json(sheet, { defval: "" });

            setExcelHeaders(json.length ? Object.keys(json[0]) : []);
            setExcelData(json);
        } catch (err) {
            console.error(err);
        }
    };

    // Helpers
    const resetForm = () => {
        setPartType("");
        setPassType("BATCH");
        setDocFile(null);
        setRemark("");
    };

    const handleRowDoubleClick = (row) => {
        const qa = (row.qa || "").trim().toUpperCase();
        if (["RERELEASED", "SCRAPPED", "SENT BACK"].includes(qa)) return;

        resetForm();
        setSelectedRow(row);
        setShowModal(true);
    };

    const handleAction = async (type) => {
        try {
            const formData = new FormData();
            formData.append("incomingId", selectedRow.incomingMaterialId);
            formData.append("qaStatus", type);
            formData.append("partType", partType);
            formData.append("passType", passType);
            formData.append("remark", remark);
            formData.append("moduleType", "QUARANTINE");

            if (docFile) formData.append("document", docFile);

            await saveQaAction(formData);

            setShowModal(false);
            resetForm();
            fetchData();
        } catch {
            alert("Error saving data");
        }
    };

    const openHistory = async (row) => {
        try {
            const res = await getHistoryLogs(row.incomingMaterialId);
            setHistoryData(res.data || []);
            setShowHistoryModal(true);
        } catch {
            alert("Failed to fetch history");
        }
    };

    const handleFilterChange = (field, value) => {
        setPage(0);
        setFilters(prev => ({ ...prev, [field]: value }));
    };
const statusClass = (qa) => {
    const upper = (qa || "").toUpperCase();

    if (upper === "RERELEASED") return "status-badge released";
    if (upper === "SCRAPPED") return "status-badge scrap";
    if (upper === "SENT BACK") return "status-badge sendback";
    if (upper === "REJECTED") return "status-badge rejected";
if (upper === "EXPIRED") return "status-badge expired";
    return "status-badge pending";
};

    return (
        <div style={{ display: "flex", flexDirection: "column", height: "100%", overflow: "hidden",margin : "10px 10px" }}>

            {/* HEADER */}
            <div style={{
                background: "#0f6b5b",
                color: "white",
                padding: "0 20px",
                height: "52px",
                display: "flex",
                alignItems: "center",
                justifyContent: "flex-end"
            }}>
                <h5 style={{ margin: 0, fontWeight: 600 }}>
                    🗂 Quality Window — Quarantine
                </h5>
            </div>

            {/* FILTER */}<div style={{
                background: "#ffffff",
                borderBottom: "1px solid #dee2e6",
                padding: "8px 16px",
                display: "flex",
                gap: "10px",
                flexWrap: "wrap",
                flexShrink: 0
            }}>
                {[
                    { placeholder: "Part Name",  field: "partName" },
                    { placeholder: "Category",   field: "category" },
                    { placeholder: "Supplier",   field: "supplierName" },
                    { placeholder: "Part Type",  field: "partType" },
                    { placeholder: "Lot No",     field: "lotNumber" },
                ].map(({ placeholder, field }) => (
                    <input
                        key={field}
                        placeholder={field}
                        onChange={(e) => handleFilterChange(field, e.target.value)}
                        style={{ 
                            height: "32px",
                            padding: "0 10px",
                            fontSize: "13px",
                            border: "1px solid #ced4da",
                            borderRadius: "4px",
                            outline: "none",
                            minWidth: "130px",
                            flex: "1 1 130px"}}
                    />
                ))}
            </div>

            {/* TABLE */}
            <div style={{ flex: 1, overflow: "auto" }}>
                <Table bordered hover size="sm" 
                 style={{ marginBottom: 0, fontSize: "13px", whiteSpace: "nowrap" }}
>
                    <thead style={{ position: "sticky", top: 0, zIndex: 1 }}>
                        <tr style={{ background: "#0f6b5b", color: "white" }}>
                            {["S.No", "Part Name", "Category", "Supplier", "Part Type",
                              "Lot No", "Qty", "MFG Date", "Expire Date", "Status",
                              "Remark", "Document", "History"].map(h => (
                                <th key={h} style={{
                                    background: "#0f6b5b", color: "white",
                                    fontWeight: 500, padding: "8px 10px", border: "none"
                                }}>{h}</th>
                            ))}
                        </tr>
                    </thead>
<tbody>
    {Array.isArray(data) && data.length > 0 ? (
        data.filter(row => {
      const qa = (row.qa || "").trim().toUpperCase();
      return ["REJECTED","EXPIRED","SCRAPPED","RERELEASED","SENT BACK"].includes(qa);
  }).map((row, i) => (
            <tr key={row.incomingMaterialId} onDoubleClick={() => handleRowDoubleClick(row)}>
                <td style={{ padding: "6px 10px" }}>{i + 1 + page * pageSize}</td>
                <td style={{ padding: "6px 10px" }}>{row.partName}</td>
                <td style={{ padding: "6px 10px" }}>{row.category || "-"}</td>
                <td style={{ padding: "6px 10px" }}>{row.supplierName || "-"}</td>
                <td style={{ padding: "6px 10px" }}>{row.partType || "-"}</td>
                <td style={{ padding: "6px 10px" }}>{row.lotNumber}</td>
                <td style={{ padding: "6px 10px" }}>{row.quantity}</td>
                <td style={{ padding: "6px 10px" }}>{row.mfgDate}</td>
                <td style={{ padding: "6px 10px" }}>{row.expireDate}</td>

                <td>
                    <span className={statusClass(row.qa)}>
                        {(row.qa || "").toUpperCase()}
                    </span>
                </td>

                <td style={{ padding: "6px 10px" }}>{row.quarentineRemark || "-"}</td>

                <td style={{ padding: "6px 10px" }}>
                    {row.quarantineDocPath ? (
                        <Button size="sm" onClick={() => {
                            const url = `${window.location.origin}/WebApplication/Controllers/viewDoc?path=${row.quarantineDocPath}`;
                            setDocUrl(url);

                            const ext = row.quarantineDocPath.split(".").pop().toLowerCase();
                            setDocType(ext);

                            if (["xls","xlsx"].includes(ext)) loadExcelPreview(url);

                            setShowDocModal(true);
                        }}>
                            View
                        </Button>
                    ) : "-"}
                </td>

                <td style={{ padding: "6px 10px" }}>
                    <Button size="sm" variant="secondary"
                        style={{ fontSize: "11px", padding: "2px 8px" }}
                        onClick={() => openHistory(row)}>
                        History
                    </Button>
                </td>
            </tr>
        ))
    ) : (
        <tr>
            <td colSpan={13} style={{ textAlign: "center", padding: "40px", color: "#999" }}>
                No Data Available
            </td>
        </tr>
    )}
</tbody>
                </Table>
            </div>

            {/* PAGER */}
            <Pager
                currentPage={page}
                totalPages={totalPages}
                onPageChange={setPage}
                pageSize={pageSize}
                onPageSizeChange={(s) => { setPageSize(s); setPage(0); }}
            />

            {/* QA MODAL */}
            
             {/* MODAL */}
             <Modal show={showModal} onHide={() => setShowModal(false)}>
                 <Modal.Header closeButton>
                     <Modal.Title>QA Action</Modal.Title>
                 </Modal.Header>
                 <Modal.Body>
                     <Form>
                         <Form.Group className="mt-2">
                             <Form.Label>Pass</Form.Label>
                             <Form.Select value={passType} onChange={(e) => setPassType(e.target.value)}>
                                 <option value="BATCH">Batch</option>
                                 <option value="LOT">Lot</option>
                             </Form.Select>
                         </Form.Group>

                         <Form.Group className="mt-2">
                             <Form.Label>Remark</Form.Label>
                           <Form.Control
                                as="textarea"
                                rows={2}
                                value={remark}
                                onChange={(e) => setRemark(e.target.value)}
                                placeholder="Enter remark..."
                            />
                        </Form.Group>

                        <Form.Group className="mt-2">
                            <Form.Label>Upload Document</Form.Label>
                            <Form.Control
                                type="file"
                                onChange={(e) => setDocFile(e.target.files[0])}
                            />
                        </Form.Group>


                        <Form.Group className="mb-2">
                            <Form.Label>MFG Date</Form.Label>
                            <Form.Control value={selectedRow?.mfgDate || ""} readOnly />
                        </Form.Group>

                        <Form.Group className="mb-2">
                            <Form.Label>Expire Date</Form.Label>
                            <Form.Control value={selectedRow?.expireDate || ""} readOnly />
                        </Form.Group>
                    </Form>
                </Modal.Body>

                <Modal.Footer>
                    <Button variant="warning" onClick={() => handleAction("SENDBACK")}>
                        Send Back to Supplier
                    </Button>

                    <Button variant="success" onClick={() => handleAction("RERELEASE")}>
                        Re-Release
                    </Button>

                    <Button variant="danger" onClick={() => handleAction("SCRAP")}>
                        Scrap
                    </Button>
                </Modal.Footer>
            </Modal>

            <Modal
                show={showDocModal}
                onHide={() => setShowDocModal(false)}
                size="lg"
            >
                <Modal.Header closeButton>
                    <Modal.Title>View Document</Modal.Title>
                </Modal.Header>

                <Modal.Body style={{ height: "500px" }}>

                    {/* PDF VIEW */}
                    {docType === "pdf" && (
                        <iframe
                            src={docUrl}
                            width="100%"
                            height="100%"
                            style={{ border: "none" }}
                            title="PDF Viewer"
                        />
                    )}

                    {/* IMAGE VIEW */}
                    {(docType === "jpg" || docType === "jpeg" || docType === "png") && (
                        <img
                            src={docUrl}
                            alt="Document"
                            style={{ width: "100%", height: "100%", objectFit: "contain" }}
                        />
                    )}



                    {(docType === "xls" || docType === "xlsx") && (
                        <div className="excel-preview" style={{ overflow: "auto", height: "100%" }}>
                            <table style={{ width: "100%", borderCollapse: "collapse" }}>
                                <thead>
                                    <tr>
                                        {excelHeaders.map((h, i) => (
                                            <th
                                                key={i}
                                                style={{
                                                    backgroundColor: "#198754",
                                                    color: "#fff",
                                                    padding: "8px",
                                                    border: "1px solid #ddd",
                                                    fontWeight: "600"
                                                }}
                                            >
                                                {h}
                                            </th>
                                        ))}
                                    </tr>
                                </thead>

                                <tbody>
                                    {excelData.map((row, i) => (
                                        <tr
                                            key={i}
                                            style={{
                                                backgroundColor: i % 2 === 0 ? "#ffffff" : "#fafafa"
                                            }}
                                        >
                                            {excelHeaders.map((h, j) => (
                                                <td
                                                    key={j}
                                                    style={{
                                                        padding: "6px 10px",
                                                        border: "1px solid #ddd",
                                                        fontSize: "13px"
                                                    }}
                                                >
                                                    {row[h]}
                                                </td>
                                            ))}
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    )}

                    {/* DEFAULT */}
                    {!(docType === "pdf" ||
                        docType === "jpg" ||
                        docType === "jpeg" ||
                        docType === "png" ||
                        docType === "xls" ||
                        docType === "xlsx") && (
                            <div>
                                <p>Preview not supported.</p>
                                <a href={docUrl} target="_blank" rel="noreferrer">
                                    Download File
                                </a>
                            </div>
                        )}
                </Modal.Body>

                <Modal.Footer>
                    <Button variant="secondary" onClick={() => setShowDocModal(false)}>
                        Close
                    </Button>
                </Modal.Footer>
            </Modal>



            <Modal
                show={showHistoryModal}
                onHide={() => setShowHistoryModal(false)}
                size="lg"
                centered
            >
                <Modal.Header
                    closeButton
                    style={{
                        background: "linear-gradient(135deg, #0f5132, #198754)",
                        color: "white",
                    }}
                >
                    <Modal.Title className="fw-bold">QA History Logs</Modal.Title>
                </Modal.Header>

                <Modal.Body style={{ background: "#f8f9fa" }}>
                    <div
                        style={{
                            background: "white",
                            borderRadius: "12px",
                            padding: "15px",
                            boxShadow: "0 6px 15px rgba(0,0,0,0.08)",
                            maxHeight: "400px",
                            overflowY: "auto",
                        }}
                    >
                        <Table bordered hover responsive className="align-middle mb-0">
                            <thead style={{ background: "#198754", color: "white" }}>
                                <tr>
                                    <th style={{ width: "70px" }}>S.No</th>
                                    <th>QA Status</th>
                                    <th>Created By</th>
                                    <th>Remark</th>
                                    <th>Status</th>

                                    <th>Date Time</th>
                                </tr>
                            </thead>

                            <tbody>
                                {historyData.length > 0 ? (
                                    historyData.map((log, index) => (
                                        <tr key={log.qualityIncomingId}>
                                            <td className="fw-semibold text-center">{index + 1}</td>

                                            <td className="fw-semibold">
                                                <span
                                                    style={{
                                                        padding: "6px 12px",
                                                        borderRadius: "20px",
                                                        fontSize: "12px",
                                                        fontWeight: "600",
                                                        background:
                                                            log.qaStatus?.toUpperCase() === "RELEASED"
                                                                ? "#d1e7dd"
                                                                : log.qaStatus?.toUpperCase() === "REJECTED"
                                                                    ? "#f8d7da"
                                                                    : "#fff3cd",
                                                        color:
                                                            log.qaStatus?.toUpperCase() === "RELEASED"
                                                                ? "#0f5132"
                                                                : log.qaStatus?.toUpperCase() === "REJECTED"
                                                                    ? "#842029"
                                                                    : "#664d03",
                                                    }}
                                                >
                                                    {log.qaStatus || "PENDING"}
                                                </span>
                                            </td>

                                            <td>{log.createdBy || "-"}</td>
                                            <td>{log.remark || "-"}</td>

                                            <td>
                                                <span
                                                    style={{
                                                        padding: "6px 12px",
                                                        borderRadius: "10px",
                                                        fontSize: "12px",
                                                        fontWeight: "600",
                                                        background: "#e9ecef",
                                                        color: "#212529",
                                                    }}
                                                >
                                                    {log.status || "-"}
                                                </span>
                                            </td>

                                            <td style={{ fontSize: "13px", color: "#555" }}>
                                                {log.dateTimeCreation || "-"}
                                            </td>
                                        </tr>
                                    ))
                                ) : (
                                    <tr>
                                        <td colSpan="5" className="text-center text-muted fw-semibold py-3">
                                            No History Found
                                        </td>
                                    </tr>
                                )}
                            </tbody>
                        </Table>
                    </div>
                </Modal.Body>

                <Modal.Footer style={{ background: "#f8f9fa" }}>
                    <Button variant="secondary" onClick={() => setShowHistoryModal(false)}>
                        Close
                    </Button>
                </Modal.Footer>
            </Modal>

        </div>
    );
};

export default QuarantineModule;





