import React, { useEffect, useState } from "react";
import { Table, Button } from "react-bootstrap";
import { useOutletContext } from "react-router-dom";
import { getQuarantineReprint, reprintgetQuarantine } from "../../api/quarantineReprintApi";

const QuarantineReprint = () => {
    const { page, setPage, totalRows, setTotalRows } = useOutletContext();

    const [data, setData] = useState([]);
    const [filters, setFilters] = useState({
        partName: "",
        category: "",
        supplierName: "",
        partType: "",
        lotNumber: ""
    });

    // 🔹 Fetch Data
    const fetchData = async () => {
        try {
            const res = await getQuarantineReprint(page, 10, filters);
            setData(res.data?.data || []);
            setTotalRows(res.data?.total || 0);
        } catch (err) {
            console.error(err);
            setData([]);
        }
    };

    useEffect(() => {
        fetchData();
    }, [page, filters]);

    // 🔹 Print Handler
    const handlePrint = async (id) => {
        try {
            const res = await reprintgetQuarantine(id);
            alert(res.data.message);
        } catch (err) {
            console.error(err);
            alert("Print failed");
        }
    };

    // 🔹 Status Badge (clean & reusable)
    const statusClass = (qa) => {
        if (!qa) return "status-badge pending";
        const upper = qa.trim().toUpperCase();

        if (upper === "RERELEASED") return "status-badge released";
        if (upper === "SCRAPPED") return "status-badge scrap";
        if (upper === "SENT BACK") return "status-badge sendback";
        if (upper === "REJECTED" || upper === "EXPIRED") return "status-badge rejected";

        return "status-badge pending";
    };

    return (
        <div style={{ display: "flex", flexDirection: "column", height: "100%", overflow: "hidden" ,margin : "10px 10px"}}>

            {/* 🔷 HEADER */}
            {/* <div style={{
                background: "#0f6b5b",
                color: "white",
                padding: "0 20px",
                height: "52px",
                display: "flex",
                alignItems: "center",
                justifyContent: "flex-end"
            }}>
                <h5 style={{ margin: 0, fontWeight: 600 }}>
                    🗂 Quality Window — Quarantine Reprint
                </h5>
            </div> */}

            {/* 🔍 FILTER BAR */}
            <div style={{
                background: "#ffffff",
                borderBottom: "1px solid #dee2e6",
                padding: "8px 16px",
                display: "flex",
                gap: "10px",
                flexWrap: "wrap",
                flexShrink: 0
            }}>
                {[
                    { placeholder: "Part Name", field: "partName" },
                    { placeholder: "Category", field: "category" },
                    { placeholder: "Supplier", field: "supplierName" },
                    { placeholder: "Part Type", field: "partType" },
                    { placeholder: "Lot No", field: "lotNumber" },
                ].map(({ placeholder, field }) => (
                    <input
                        key={field}
                        placeholder={placeholder}
                        onChange={(e) => {
                            setPage(0);
                            setFilters(prev => ({ ...prev, [field]: e.target.value }));
                        }}
                        style={{
                            height: "32px",
                            padding: "0 10px",
                            fontSize: "13px",
                            border: "1px solid #ced4da",
                            borderRadius: "4px",
                            outline: "none",
                            minWidth: "130px",
                            flex: "1 1 130px"
                        }}
                    />
                ))}
            </div>

            {/* 📊 TABLE */}
            <div style={{ flex: 1, overflow: "auto" }}>
                <Table
                    bordered
                    hover
                    size="sm"
                    style={{ marginBottom: 0, fontSize: "13px", whiteSpace: "nowrap" }}
                >
                    <thead style={{ position: "sticky", top: 0, zIndex: 1 }}>
                        <tr style={{ background: "#0f6b5b", color: "white" }}>
                            {["S.No", "Part Name", "Category", "Supplier", "Part Type",
                              "Lot No", "Qty", "MFG Date", "Expire Date", "Status", "Print"].map(h => (
                                <th key={h} style={{
                                    background: "#0f6b5b",
                                    color: "white",
                                    fontWeight: 500,
                                    padding: "8px 10px",
                                    border: "none"
                                }}>
                                    {h}
                                </th>
                            ))}
                        </tr>
                    </thead>

                    <tbody>
                        {Array.isArray(data) && data.length > 0 ? data.map((row, index) => (
                            <tr
                                key={row.incomingMaterialId}
                                style={{
                                    background:
                                        (row.qa || "").trim().toUpperCase() === "EXPIRED"
                                            ? "#fff3cd"
                                            : index % 2 === 0
                                                ? "#ffffff"
                                                : "#f8f9fa"
                                }}
                            >
                                <td style={{ padding: "6px 10px" }}>{index + 1 + page * 10}</td>
                                <td style={{ padding: "6px 10px", fontWeight: 500 }}>{row.partName}</td>
                                <td style={{ padding: "6px 10px" }}>{row.category || "-"}</td>
                                <td style={{ padding: "6px 10px" }}>{row.supplierName || "-"}</td>
                                <td style={{ padding: "6px 10px" }}>{row.partType || "-"}</td>
                                <td style={{ padding: "6px 10px" }}>{row.lotNumber}</td>
                                <td style={{ padding: "6px 10px" }}>{row.quantity}</td>
                                <td style={{ padding: "6px 10px" }}>{row.mfgDate}</td>
                                <td style={{ padding: "6px 10px" }}>{row.expireDate}</td>

                                {/* STATUS */}
                                <td style={{ padding: "6px 10px" }}>
                                    <span className={statusClass(row.qa)}>
                                        {(row.qa || "").trim().toUpperCase() || "PENDING"}
                                    </span>
                                </td>

                                {/* PRINT */}
                                <td style={{ padding: "6px 10px" }}>
                                    <Button
                                        size="sm"
                                        variant="primary"
                                        onClick={() => handlePrint(row.incomingMaterialId)}
                                    >
                                        Print
                                    </Button>
                                </td>
                            </tr>
                        )) : (
                            <tr>
                                <td colSpan={11} style={{ textAlign: "center", padding: "40px", color: "#999" }}>
                                    No Data Available
                                </td>
                            </tr>
                        )}
                    </tbody>
                </Table>
            </div>
        </div>
    );
};

export default QuarantineReprint;


