import React, { useState, useEffect } from "react";
import { Link, NavLink } from "react-router-dom";
import { BoxArrowRight, List, Back } from "react-bootstrap-icons";
import { Database } from "lucide-react";
import "bootstrap/dist/css/bootstrap.min.css";
import "../css/SideBar.css";
import {
  FaBox, FaBoxes, FaBuilding, FaClipboardList,
  FaClock, FaFlask, FaIndustry, FaTruck,
  FaUser, FaUserShield
} from "react-icons/fa";
import { OverlayTrigger, Tooltip } from "react-bootstrap";
import SearchInputFields from "./SearchInputFields";

const Sidebar = ({ moduleName }) => {
  const [isCollapsed, setIsCollapsed] = useState(false);
  const [searchText, setSearchText] = useState("");

  const masterList = [



    // ── Quality ──
    { key: "incoming", label: "Incoming", icon: <FaTruck size={18} />, group: "Quality" },
    { key: "quarantine", label: "Quarantine", icon: <FaFlask size={18} />, group: "Quality" },

    // ── Reprint ──
    { key: "reprint/incoming", label: "Reprint – Incoming", icon: <FaBoxes size={18} />, group: "Reprint" },
    { key: "reprint/quality-print", label: "Reprint – Quality", icon: <FaClipboardList size={18} />, group: "Reprint" },
    { key: "reprint/quarantine", label: "Reprint – Quarantine", icon: <FaBox size={18} />, group: "Reprint" },
  ];

  const filteredList = masterList.filter(item =>
    item.label.toLowerCase().includes(searchText.toLowerCase()) ||
    item.key.toLowerCase().includes(searchText.toLowerCase())
  );

  const renderedGroups = new Set();

  useEffect(() => {
    const handleResize = () => setIsCollapsed(window.innerWidth < 1500);
    window.addEventListener("resize", handleResize);
    handleResize();
    return () => window.removeEventListener("resize", handleResize);
  }, []);

  return (
    <div
      className="d-flex flex-column text-white"
      style={{
        width: isCollapsed ? "50px" : "260px",
        height: "100vh",
        position: "sticky",
        top: 0,
        backgroundColor: "#0f6b5b",
        transition: "width 0.2s ease"
      }}
    >
      {/* Toggle */}
      <button
        className="btn btn-sm btn-outline-light m-2 p-0"
        onClick={() => setIsCollapsed(!isCollapsed)}
      >
        <List size={28} />
      </button>

      {/* Logo + Search */}
      {!isCollapsed && (
        <div>
          <a
            href="/WebApplication/dashboard"
            className="d-flex align-items-center mb-3 text-white text-decoration-none px-3"
          >
            <span className="fs-5 fw-bold">
              <Database size={20} className="me-2" />
              {moduleName}
            </span>
          </a>
          <div className="px-3">
            <SearchInputFields
              type="text"
              placeholder="Search..."
              value={searchText}
              onChange={(e) => setSearchText(e.target.value)}
            />
          </div>
        </div>
      )}

      <hr className="border-light mx-2" />

      {/* Menu */}
      <div
        className={isCollapsed ? "flex-grow-1" : "flex-grow-1 sidebar-scroll"}
        style={{ overflowY: isCollapsed ? "hidden" : "auto" }}
      >
        <ul className="nav nav-pills flex-column mb-auto">
          {filteredList.map(item => {

            let groupDivider = null;
            if (!isCollapsed && item.group && !renderedGroups.has(item.group)) {
              renderedGroups.add(item.group);
              groupDivider = (
                <li key={`group-${item.group}`} style={{
                  padding: "8px 14px 2px",
                  fontSize: "10px",
                  fontWeight: 700,
                  color: "rgba(255,255,255,0.5)",
                  textTransform: "uppercase"
                }}>
                  {item.group}
                </li>
              );
            }

            const navLink = isCollapsed ? (
              <OverlayTrigger
                key={item.key}
                placement="right"
                overlay={<Tooltip>{item.label}</Tooltip>}
              >
                <div style={{ width: "100%" }}>
                  <NavLink
                    to={item.key}
                    className={({ isActive }) =>
                      `nav-link d-flex justify-content-center ${isActive ? "sidebar-active" : "text-white"}`
                    }
                  >
                    {item.icon}
                  </NavLink>
                </div>
              </OverlayTrigger>
            ) : (
              <NavLink
                key={item.key}
                to={item.key}
                className={({ isActive }) =>
                  `nav-link d-flex align-items-center px-3 ${isActive ? "sidebar-active" : "text-white"}`
                }
              >
                <span className="me-2">{item.icon}</span>
                {item.label}
                <span className="ms-auto">›</span>
              </NavLink>
            );

            return (
              <React.Fragment key={item.key}>
                {groupDivider}
                <li className="nav-item">{navLink}</li>
              </React.Fragment>
            );
          })}
        </ul>
      </div>

      <hr className="border-light mx-2" />

      {/* Bottom */}
      <ul className="nav nav-pills flex-column">
        <li className="nav-item">
          <Link
            onClick={() => window.location.href = "/WebApplication/moduleDashboard"}
            className="nav-link text-white d-flex align-items-center px-3"
          >
            <Back size={20} className="me-2" />
            {!isCollapsed && "Go To Dashboard"}
          </Link>
        </li>

        <li className="nav-item">
          <Link
            to="logout"
            className="nav-link text-white d-flex align-items-center px-3"
          >
            <BoxArrowRight size={20} className="me-2" />
            {!isCollapsed && "Logout"}
          </Link>
        </li>
      </ul>
    </div>
  );
};

export default Sidebar;