import React, { useState } from "react";
import { Outlet } from "react-router-dom";
import Sidebar from "../../component/SideBar";          // adjust path as needed
import DismissableAlert from "../../component/DismissableAlert";
import { AnimatePresence, motion } from "framer-motion";


function QualityDashboard() {
    const [alert, setAlert] = useState(null);

    return (
        <div className="d-flex" style={{ height: "100vh", overflow: "hidden" }}>

            {/* ── SIDEBAR (identical to master) ── */}
            <div style={{ flexShrink: 0 }}>
                <Sidebar moduleName="Quality" />
            </div>

            {/* ── MAIN CONTENT AREA ── */}
            <div
                className="flex-grow-1"
                style={{
                    overflowY: "hidden",
                    height: "100vh",
                    display: "flex",
                    flexDirection: "column"
                }}
            >
                {/* Global alert (optional – reuse from master) */}
                <DismissableAlert
                    alert={alert}
                    setDismissAlertNull={() => setAlert(null)}
                />

                {/* Animated page transitions */}
                <AnimatePresence mode="wait">
                    <motion.div
                        style={{ flex: 1, display: "flex", flexDirection: "column", overflow: "hidden" }}
                        initial={{ x: "100%", opacity: 0 }}
                        animate={{ x: 0, opacity: 1 }}
                        transition={{ duration: 0.4, ease: "easeInOut" }}
                    >
                        {/* Child routes render here — they receive setAlert via context if needed */}
                        <Outlet context={{ setAlert }} />
                    </motion.div>
                </AnimatePresence>
            </div>
        </div>
    );
}

export default QualityDashboard;





