import React from "react";
import { ChevronLeft, ChevronRight } from "lucide-react";

const Pager = ({ currentPage, totalPages, onPageChange, pageSize, onPageSizeChange }) => {
  return (

    <div
      className="container-fluid py-1"
      style={{
        background: "#ffffff",
        borderTop: "1px solid #e5e7eb"
      }}
    >
      <div className="row align-items-center text-center text-md-start">

        {/* LEFT - ROWS PER PAGE */}
        <div className="col-12 col-md-4 mb-2 mb-md-0">
          <div className="d-flex justify-content-center justify-content-md-start align-items-center gap-2">
            <span style={{ fontWeight: 500, color: "#0f6b5b" }}>
              Rows:
            </span>

            <select
              value={pageSize}
              onChange={(e) => onPageSizeChange(Number(e.target.value))}
              className="form-select form-select-sm"
              style={{
                maxWidth: "90px",
                borderColor: "#0f6b5b"
              }}
            >
              {[10, 25, 50, 100].map((size) => (
                <option key={size} value={size}>
                  {size}
                </option>
              ))}
            </select>
          </div>
        </div>

        {/* RIGHT - NAVIGATION */}
        <div className="col-8">
          <div className="d-flex justify-content-center align-items-center justify-content-md-end gap-2">

            <button
              disabled={currentPage === 0}
              onClick={() => onPageChange(currentPage - 1)}
              className="btn btn-sm mx-1"
              style={{
                border: "1px solid #d1d5db",
                background: currentPage === 0 ? "#e5e7eb" : "#ffffff",
                color: currentPage === 0 ? "#9ca3af" : "#0f6b5b"
              }}
            >
              ‹ Prev
            </button>

            <span style={{ fontWeight: 500, color: "#0f6b5b" }}>
              Page
            </span>

            <select
              value={currentPage}
              onChange={(e) => onPageChange(Number(e.target.value))}
              className="form-select form-select-sm"
              style={{
                maxWidth: "90px",
                borderColor: "#0f6b5b"
              }}
            >
              {Array.from({ length: totalPages }, (_, i) => (
                <option key={i} value={i}>
                  {i + 1}
                </option>
              ))}
            </select>

            <span style={{ fontWeight: 500, color: "#0f6b5b" }}>
              of {totalPages}
            </span>

            <button
              disabled={currentPage === totalPages - 1}
              onClick={() => onPageChange(currentPage + 1)}
              className="btn btn-sm mx-1"
              style={{
                border: "1px solid #d1d5db",
                background:
                  currentPage === totalPages - 1 ? "#e5e7eb" : "#ffffff",
                color:
                  currentPage === totalPages - 1 ? "#9ca3af" : "#0f6b5b"
              }}
            >
              Next ›
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Pager;
